// ─── search surfacing ────────────────────────────────────────────────────────

func TestCmdSearch_ReportsRecordsAsRecords(t *testing.T) {
	kb, root := openWorkspaceKB(t)
	dir := filepath.Join(root, "clasm", "decisions")
	testRecord{ID: "0160", Project: "clasm",
		Title: "Associate the IAM instance profile",
		Body:  "\n**Context.** A distinctive phrase: zzyzxmarker.\n"}.write(t, dir)
	runIngest(t, kb, dir)

	results, err := kb.Search("zzyzxmarker")
	if err != nil {
		t.Fatalf("Search: %v", err)
	}
	if len(results) == 0 {
		t.Fatal("no results for a record body")
	}
	found := false
	for _, r := range results {
		if r.SourceType == "record" {
			found = true
			if r.Label != "DR-0160" {
				t.Errorf("Label = %q, want DR-0160", r.Label)
			}
		}
	}
	if !found {
		t.Errorf("results = %+v, want one labelled source_type record", results)
	}
}

func TestCmdSearch_StillReportsOtherSourceTypes(t *testing.T) {
	kb, _ := openWorkspaceKB(t)
	pid, err := kb.AddProject("clasm", "distinctive qqxmarker project")
	if err != nil {
		t.Fatalf("AddProject: %v", err)
	}
	if _, err := kb.AddObservation(pid, "note", "another qqxmarker observation"); err != nil {
		t.Fatalf("AddObservation: %v", err)
	}
	results, err := kb.Search("qqxmarker")
	if err != nil {
		t.Fatalf("Search: %v", err)
	}
	seen := map[string]bool{}
	for _, r := range results {
		seen[r.SourceType] = true
	}
	if !seen["project"] || !seen["observation"] {
		t.Errorf("source types seen = %v, want project and observation still reported", seen)
	}
}

// ─── invariants ported from decisions_index_test.ts ──────────────────────────

// The longest value in each vocabulary must fit its column without being
// truncated, or the index would misreport a record's status or trigger.
func TestCmdIndex_DoesNotTruncateLongestVocabularyValues(t *testing.T) {
	kb, root := openWorkspaceKB(t)
	dir := filepath.Join(root, "clasm", "decisions")
	testRecord{ID: "0001", Project: "clasm", Status: "superseded",
		Kind: "refinement", Trigger: "release-review"}.write(t, dir)

	var out bytes.Buffer
	if err := cmdIndex(kb, nil, false, []string{dir, "--stdout"}, &out); err != nil {
		t.Fatalf("cmdIndex: %v", err)
	}
	f := strings.Fields(strings.Split(out.String(), "```\n")[1])
	for i, want := range map[int]string{2: "superseded", 3: "refinement", 4: "release-review"} {
		if f[i] != want {
			t.Errorf("field %d = %q, want %q — the column truncated it", i, f[i], want)
		}
	}
}

// Records are NNNN-slug.md. The generated index.md is in the same directory on
// every run after the first, and must never be read back in as a record.
func TestCmdIndex_IgnoresNonRecordFiles(t *testing.T) {
	kb, root := openWorkspaceKB(t)
	dir := filepath.Join(root, "clasm", "decisions")
	testRecord{ID: "0001", Project: "clasm"}.write(t, dir)
	writeRaw(t, dir, "README.md", "# Prose, not a record\n")
	writeRaw(t, dir, "notes.md", "Also not a record\n")

	var out bytes.Buffer
	if err := cmdIndex(kb, nil, false, []string{dir}, &out); err != nil {
		t.Fatalf("cmdIndex: %v", err)
	}
	// Second run, with index.md now present alongside them.
	out.Reset()
	if err := cmdIndex(kb, nil, false, []string{dir, "--stdout"}, &out); err != nil {
		t.Fatalf("second cmdIndex: %v", err)
	}
	rows := 0
	for _, line := range strings.Split(out.String(), "\n") {
		if strings.HasPrefix(line, "DR-") {
			rows++
		}
	}
	if rows != 1 {
		t.Errorf("index has %d rows, want 1 — a non-record file was read as a record", rows)
	}
}

// relates_to is not an index column, so a qualified cross-tier reference must
// pass through without disturbing anything.
func TestCmdIndex_QualifiedRelatesToDoesNotDisturbTheIndex(t *testing.T) {
	kb, root := openWorkspaceKB(t)
	dir := filepath.Join(root, "agents", "decisions")
	testRecord{ID: "0001", Project: "", RelatesTo: []string{"clasm:0160"}}.write(t, dir)

	var out bytes.Buffer
	if err := cmdIndex(kb, nil, false, []string{dir, "--stdout"}, &out); err != nil {
		t.Fatalf("cmdIndex: %v", err)
	}
	if strings.Contains(out.String(), "clasm:0160") {
		t.Errorf("a relates_to entry leaked into the index:\n%s", out.String())
	}
	if f := strings.Fields(strings.Split(out.String(), "```\n")[1]); len(f) < 7 || f[0] != "DR-0001" {
		t.Errorf("row = %q, want a well-formed DR-0001 row", out.String())
	}
}

